import { readFileSync, readdirSync, writeFileSync } from "node:fs";
const files = readdirSync("supabase/migrations")
  .filter((f) => f.endsWith(".sql"))
  .sort();
const migrations = files.map(file =>
  "\n-- " + file + "\n" + readFileSync("supabase/migrations/" + file, "utf8")
).join("\n");
writeFileSync("supabase/setup.sql",
  "-- Generated by npm run supabase:bundle. Apply ONCE to a NEW Supabase project.\nbegin;\n" + migrations + "\ncommit;\n"
);
// The PUBLIC role is intentionally preserved; only qualified schema references change.
// The shared installation never alters unrelated public tables, grants or Auth settings.
const shared = migrations
  .replace(/\bpublic\./g, "familyos.")
  .replace(/search_path=public,pg_temp/g, "search_path=familyos,pg_temp")
  .replace("revoke create on schema public from public;", "revoke create on schema familyos from public;");
writeFileSync("supabase/shared-setup.sql",
  "-- Generated by npm run supabase:bundle. Apply ONCE to a project without a familyos schema.\n" +
  "-- Shared Auth belongs to the project; keep existing global configuration and other applications intact.\n" +
  "begin;\ncreate schema familyos;\nrevoke all on schema familyos from public;\ngrant usage on schema familyos to authenticated,service_role;\n" +
  shared + "\ncommit;\n"
);
